/**
 * Schema of `public/examples/manifest.json`, the file generated by
 * `fixtures/build-fixtures.mjs`.
 *
 * An I/O boundary: the manifest arrives as untrusted JSON (`fetch` in the browser, disk in a
 * test) and becomes a domain type only after zod validation. The types are derived from the
 * schema with `z.infer` so the two cannot drift apart.
 */

import { z } from 'zod';

const nonEmptyText = z.string().trim().min(1);

export const exampleEntrySchema = z
  .object({
    /** Stable kebab-case identifier; used in the URL and in differential tests. */
    id: z
      .string()
      .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'id must be kebab-case (e.g. "sum-of-products")'),
    /** Example name shown in the UI. */
    title: nonEmptyText,
    /** One line for the welcome card — short enough that it never has to be truncated. */
    tagline: nonEmptyText.max(60),
    /** Educational description: what the example demonstrates in bytecode terms. */
    description: nonEmptyText,
    /** File name inside `public/examples/`, not a path — the directory is fixed. */
    classFile: z.string().regex(/^[A-Za-z][A-Za-z0-9]*\.class$/),
    sourceFile: z.string().regex(/^[A-Za-z][A-Za-z0-9]*\.java$/),
    /** Interpreter entry point convention. */
    entryMethod: z.literal('main'),
    /** Local variable in `main` the example stores its result in. */
    resultVariable: z.literal('result'),
    /**
     * Result computed by a REAL JVM during the fixtures build — the reference value for the
     * differential test. A JVM `int`, so it must fit the signed 32-bit range.
     */
    expectedResult: z.int().min(-2_147_483_648).max(2_147_483_647),
  })
  .strict();

export const exampleManifestSchema = z
  .object({
    /** Manifest format version; bumping it requires updating this schema. */
    version: z.literal(1),
    examples: z
      .array(exampleEntrySchema)
      .min(1)
      .refine(
        (examples) => new Set(examples.map((example) => example.id)).size === examples.length,
        { message: 'example identifiers must be unique' },
      ),
  })
  .strict();

export type ExampleEntry = z.infer<typeof exampleEntrySchema>;
export type ExampleManifest = z.infer<typeof exampleManifestSchema>;

/**
 * Validates the raw manifest JSON. Throws a `z.ZodError` carrying the full error path —
 * the caller decides whether to turn it into a UI message or treat it as a programmer error.
 */
export function parseExampleManifest(raw: unknown): ExampleManifest {
  return exampleManifestSchema.parse(raw);
}
